import trimesh, os, json

base = '/root/miniconda3/envs/libero/lib/python3.10/site-packages/robosuite/models/assets'
results = {'total': 0, 'watertight': 0, 'not_watertight': 0, 'load_failed': 0, 'by_category': {}}

for root, dirs, files in os.walk(base):
    for f in files:
        if not f.lower().endswith(('.stl', '.obj')):
            continue
        fpath = os.path.join(root, f)
        rel = os.path.relpath(root, base)
        cat = rel.split('/')[0] if '/' in rel else rel

        results['total'] += 1
        if cat not in results['by_category']:
            results['by_category'][cat] = {'total': 0, 'watertight': 0, 'not_watertight': 0, 'failed': 0}
        results['by_category'][cat]['total'] += 1

        try:
            mesh = trimesh.load(fpath, force='mesh')
            if mesh.is_watertight:
                results['watertight'] += 1
                results['by_category'][cat]['watertight'] += 1
            else:
                results['not_watertight'] += 1
                results['by_category'][cat]['not_watertight'] += 1
        except Exception as e:
            results['load_failed'] += 1
            results['by_category'][cat]['failed'] += 1

print(f\"Total meshes: {results['total']}\")
print(f\"Watertight: {results['watertight']} ({100*results['watertight']/results['total']:.1f}%)\")
print(f\"Not watertight: {results['not_watertight']} ({100*results['not_watertight']/results['total']:.1f}%)\")
print(f\"Load failed: {results['load_failed']}\")
print()
for cat, d in sorted(results['by_category'].items()):
    print(f\"  {cat}: {d['total']} total, {d['watertight']} watertight, {d['not_watertight']} non-watertight, {d['failed']} failed\")
